180	InputOrderInfoPtr ReadInOrderOptimizer::getInputOrderImpl(
181	    const StorageMetadataPtr & metadata_snapshot,
182	    const SortDescription & description,
183	    const ManyExpressionActions & actions,
184	    UInt64 limit) const
185	{
186	    auto sorting_key_columns = metadata_snapshot->getSortingKeyColumns();
187	    int read_direction = description.at(0).direction;
188	
189	    size_t fixed_prefix_size = calculateFixedPrefixSize(query, sorting_key_columns);
190	    size_t descr_prefix_size = std::min(description.size(), sorting_key_columns.size() - fixed_prefix_size);
191	
192	    SortDescription order_key_prefix_descr;
193	    order_key_prefix_descr.reserve(descr_prefix_size);
194	
195	    for (size_t i = 0; i < descr_prefix_size; ++i)
196	    {
197	        if (forbidden_columns.contains(description[i].column_name))
198	            break;
199	
200	        int current_direction = matchSortDescriptionAndKey(
201	            actions[i]->getActions(), description[i], sorting_key_columns[i + fixed_prefix_size]);
202	
203	        if (!current_direction || (i > 0 && current_direction != read_direction))
204	            break;
205	
206	        if (i == 0)
207	            read_direction = current_direction;
208	
209	        order_key_prefix_descr.push_back(required_sort_description[i]);
210	    }
211	
212	    if (order_key_prefix_descr.empty())
213	        return {};
214	
215	    SortDescription order_key_fixed_prefix_descr;
216	    order_key_fixed_prefix_descr.reserve(fixed_prefix_size);
217	    for (size_t i = 0; i < fixed_prefix_size; ++i)
218	        order_key_fixed_prefix_descr.emplace_back(sorting_key_columns[i], read_direction);
219	
220	    return std::make_shared<InputOrderInfo>(
221	        std::move(order_key_fixed_prefix_descr),
222	        std::move(order_key_prefix_descr),
223	        read_direction, limit);
