125	size_t DistinctSortedChunkTransform::getRangeEnd(size_t begin, size_t end) const
126	{
127	    assert(begin < end);
128	
129	    const size_t linear_probe_threadhold = 16;
130	    size_t linear_probe_end = begin + linear_probe_threadhold;
131	    if (linear_probe_end > end)
132	        linear_probe_end = end;
133	
134	    for (size_t pos = begin; pos < linear_probe_end; ++pos)
135	    {
136	        if (!isCurrentKey(pos))
137	            return pos;
138	    }
139	
140	    size_t low = linear_probe_end;
141	    size_t high = end - 1;
142	    while (low <= high)
143	    {
144	        size_t mid = low + (high - low) / 2;
145	        if (isCurrentKey(mid))
146	            low = mid + 1;
147	        else
148	        {
149	            high = mid - 1;
150	            end = mid;
151	        }
152	    }
153	    return end;
154	}
