159	    /// or first row doesn't match a key from previous transform()
160	    if (current_key.empty() || !isCurrentKey(0))
161	        return {0, 0};
162	
163	    size_t output_rows = 0;
164	    const size_t range_end = getRangeEnd(0, chunk_rows);
165	    if (other_columns.empty())
166	        std::fill(filter.begin(), filter.begin() + range_end, 0); /// skip rows already included in distinct on previous transform()
167	    else
168	        output_rows = ordinaryDistinctOnRange(filter, 0, range_end, false);
169	
