173	void DistinctSortedChunkTransform::transform(Chunk & chunk)
174	{
175	    const size_t chunk_rows = chunk.getNumRows();
176	    if (unlikely(0 == chunk_rows))
177	        return;
178	
179	    Columns input_columns = chunk.detachColumns();
180	    /// split input columns into sorted and other("non-sorted") columns
181	    initChunkProcessing(input_columns);
182	
183	    /// build filter:
184	    /// (1) find range with the same values in sorted columns -> [range_begin, range_end)
185	    /// (2) for found range
186	    ///     if there is no "non-sorted" columns: filter out all rows in range except first one
187	    ///     otherwise: apply ordinary distinct
188	    /// (3) repeat until chunk is processed
189	    IColumn::Filter filter(chunk_rows);
190	    auto [range_begin, output_rows] = continueWithPrevRange(chunk_rows, filter); /// try to process chuck as continuation of previous one
191	    size_t range_end = range_begin;
192	    while (range_end != chunk_rows)
193	    {
194	        // set current key to find range
195	        setCurrentKey(range_begin);
196	
197	        // find new range [range_begin, range_end)
198	        range_end = getRangeEnd(range_begin, chunk_rows);
199	
200	        // update filter for range
201	        if (other_columns.empty())
202	        {
203	            filter[range_begin] = 1;
204	            std::fill(filter.begin() + range_begin + 1, filter.begin() + range_end, 0);
205	            ++output_rows;
206	        }
207	        else
208	        {
209	            // ordinary distinct in range if there are "non-sorted" columns
210	            output_rows += ordinaryDistinctOnRange(filter, range_begin, range_end, true);
211	        }
212	
213	        // set where next range start
214	        range_begin = range_end;
215	    }
216	
217	    /// apply the built filter
218	    for (auto & input_column : input_columns)
219	        input_column = input_column->filter(filter, output_rows);
220	
221	    chunk.setColumns(std::move(input_columns), output_rows);
222	
223	    /// Update total output rows and check limits
224	    total_output_rows += output_rows;
225	    if ((limit_hint && total_output_rows >= limit_hint)
226	        || !output_size_limits.check(total_output_rows, data.getTotalByteCount(), "DISTINCT", ErrorCodes::SET_SIZE_LIMIT_EXCEEDED))
